import numpy as np
import pandas as pd
from datetime import datetime, timezone
import pytz

def r_time_force_tz(time, tz="UTC", tzout=None, roll_dst="boundary"):
    """
    Force time to a specified timezone, changing the timezone without changing the clock time.

    Parameters:
    - time: a datetime-like object or list of datetime-like objects
    - tz: target timezone (default "UTC")
    - tzout: output timezone (default: first element of tz)
    - roll_dst: how to handle DST transitions ("boundary" or "post")

    Returns:
    - datetime or array of datetimes with forced timezone
    """

    # Handle tzout default
    if tzout is None:
        if isinstance(tz, list):
            tzout = tz[0]
        else:
            tzout = tz

    # Handle list input (but not POSIXlt which is a special list type)
    if isinstance(time, dict):
        result = {}
        for key, val in time.items():
            if isinstance(val, (pd.Timestamp, np.datetime64, datetime)):
                result[key] = _force_tz_scalar(val, tz, tzout, roll_dst)
            elif isinstance(val, (list, np.ndarray)):
                # Check if it contains datetime-like objects
                if len(val) > 0 and isinstance(val[0], (pd.Timestamp, np.datetime64, datetime)):
                    result[key] = np.array([_force_tz_scalar(v, tz, tzout, roll_dst) for v in val])
                else:
                    result[key] = val
            else:
                result[key] = val
        return result

    # Handle array/list input
    if isinstance(time, (list, np.ndarray)):
        return np.array([_force_tz_scalar(t, tz, tzout, roll_dst) for t in time])

    # Handle scalar input
    return _force_tz_scalar(time, tz, tzout, roll_dst)


def _force_tz_scalar(time, tz, tzout, roll_dst):
    """
    Internal function to force timezone for a single datetime value.

    Force a time object into a specified timezone without changing the clock time.
    This means: take the naive local time representation and interpret it as being
    in the target timezone, then return it with that timezone attached.
    """

    # Convert input to pandas Timestamp if needed
    if isinstance(time, str):
        dt = pd.Timestamp(time)
    elif isinstance(time, np.datetime64):
        dt = pd.Timestamp(time)
    elif isinstance(time, datetime):
        dt = pd.Timestamp(time)
    else:
        dt = pd.Timestamp(time)

    # Get the naive local time (clock time without timezone info)
    local_time = dt.replace(tzinfo=None)

    # Get the target timezone object
    target_tz = pytz.timezone(tzout)

    # Try to localize the naive local time to the target timezone
    try:
        # Try normal localization
        result = target_tz.localize(local_time, is_dst=None)
    except pytz.exceptions.AmbiguousTimeError:
        # During DST transition (fall back), time is ambiguous
        if roll_dst == "boundary":
            # Use the first occurrence (before DST ends, is_dst=True)
            result = target_tz.localize(local_time, is_dst=True)
        else:  # "post"
            # Use the second occurrence (after DST ends, is_dst=False)
            result = target_tz.localize(local_time, is_dst=False)
    except pytz.exceptions.NonExistentTimeError:
        # During spring forward, time doesn't exist
        if roll_dst == "boundary":
            # Move to the boundary (the moment DST starts, which is is_dst=False for the next valid time)
            result = target_tz.localize(local_time, is_dst=False)
        else:  # "post"
            # Move forward past the gap
            result = target_tz.localize(local_time, is_dst=False)

    return result
